def blur(a, r=2, passes=2):
    for _ in range(passes):
        h, w = a.shape
        ap = np.pad(a, ((r, r), (r, r)), mode='wrap')
        out = np.zeros_like(a)
        for dy in range(-r, r + 1):
            for dx in range(-r, r + 1):
                out += ap[r + dy: r + dy + h, r + dx: r + dx + w]
        a = out / float((2 * r + 1) ** 2)
    return a

